const Tbl=({cols,data,onRow,onRowDown,onRowOver,isSel,dragging})=>{const wrR=useRef(null);const yR=useRef(null);useEffect(()=>{if(!dragging)return;const t=setInterval(()=>{const el=wrR.current,y=yR.current;if(!el||y==null)return;const b=el.getBoundingClientRect();if(y<b.top+55)el.scrollTop-=16;else if(y>b.bottom-55)el.scrollTop+=16},30);return()=>clearInterval(t)},[dragging]);return <div ref={wrR} onMouseMove={e=>{yR.current=e.clientY}} style={{borderRadius:10,border:"1px solid "+C.bd,overflow:"auto",background:C.sf,maxWidth:"100%",maxHeight:"calc(100vh - 170px)",userSelect:dragging?"none":"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13,minWidth:600}}><thead><tr>{cols.map((c,i)=><th key={i} style={{padding:"10px 12px",textAlign:"left",background:C.thBg,color:C.tD,fontSize:10,textTransform:"uppercase",letterSpacing:.8,borderBottom:"2px solid "+C.acc,whiteSpace:"nowrap",fontWeight:700,position:"sticky",top:0,zIndex:1}}>{c.label}</th>)}</tr></thead><tbody>{data.length===0?<tr><td colSpan={cols.length} style={{padding:30,textAlign:"center",color:C.tM}}>Nessun dato</td></tr>:data.map((row,ri)=>row._blank?<tr key={"bl"+ri}><td colSpan={cols.length} style={{padding:4,background:C.bg}}></td></tr>:row._sub?<tr key={"sub"+ri} style={{background:row._level==="tipo"?C.accL:row._level==="lav"?C.subBg:"transparent",borderTop:row._level==="tipo"?"2px solid "+C.acc:row._level==="lav"?"2px solid "+C.bd:"1px solid "+C.bd}}>{cols.map((c,ci)=><td key={ci} style={{padding:"7px 12px",fontWeight:row._level==="tipo"?800:row._level==="lav"?700:600,fontSize:row._level==="tipo"?12:11,color:row._level==="tipo"?C.acc:row._level==="lav"?C.subT:C.tM,whiteSpace:"nowrap",fontStyle:row._level==="cal"?"italic":"normal"}}>{c.subRender?c.subRender(row):""}</td>)}</tr>:(()=>{const sd=isSel?!!isSel(row):false;const bgB=sd?C.selBg:(ri%2===0?C.sf:C.zebra);return <tr key={row.id||ri} onClick={()=>onRow&&onRow(row)} onMouseDown={e=>{if(!onRowDown)return;const tg=e.target;if(tg&&tg.closest&&tg.closest("input,button,a,select,textarea,label"))return;e.preventDefault();onRowDown(row,e)}} style={{cursor:(onRow||onRowDown)?"pointer":"default",background:bgB,transition:"background .12s",boxShadow:sd?("inset 3px 0 0 "+C.acc):"none"}} onMouseEnter={e=>{e.currentTarget.style.background=sd?C.acc+"33":C.sfH;if(onRowOver)onRowOver(row)}} onMouseLeave={e=>{e.currentTarget.style.background=bgB}}>{cols.map((c,ci)=><td key={ci} style={{padding:"9px 12px",borderBottom:"1px solid "+C.bd+"66",whiteSpace:"nowrap",color:C.t,fontWeight:sd?600:400}}>{c.render?c.render(row):row[c.key]}</td>)}</tr>})())}</tbody></table></div>;};
