// === TRACCIABILITA (lotti padre di un semilavorato) ===
function Tracciabilita({lot}){const[par,setPar]=useState(null);const[ddtAbc,setDdtAbc]=useState(null);const[docA,setDocA]=useState(null);useEffect(()=>{let on=true;(async()=>{try{if(lot.doc_id){const{data:da}=await supabase.from("doc_abc").select("numero,data").eq("id",lot.doc_id).maybeSingle();if(on)setDocA(da||null)}const{data:bridge}=await supabase.from("trasformazione_input").select("padre_id,qta").eq("figlio_id",lot.id);const ids=[...new Set([...(bridge||[]).map(b=>b.padre_id),...(lot.lotto_padre?[lot.lotto_padre]:[])])];if(ids.length===0){if(on){setPar([]);setDdtAbc(null)}return}const{data:padri}=await supabase.from("lotti").select("*").in("id",ids);const{data:trm}=await supabase.from("movimenti").select("lotto_id,ddt,data").eq("tipo","TRASFERIMENTO").eq("magazzino","ABC Service").in("lotto_id",ids);const dMap={};(trm||[]).forEach(m=>{if(m.ddt&&String(m.ddt).trim()){if(!dMap[m.lotto_id]||String(m.data)>String(dMap[m.lotto_id].data))dMap[m.lotto_id]={ddt:m.ddt,data:m.data}}});const qById={};(bridge||[]).forEach(b=>{qById[b.padre_id]=b.qta});const out=(padri||[]).map(p=>({...p,qScar:qById[p.id],ddtAnd:dMap[p.id]?dMap[p.id].ddt:null}));if(on){setPar(out);setDdtAbc([...new Set(out.map(p=>p.ddtAnd).filter(Boolean))])}}catch(e){if(on)setPar([])}})();return()=>{on=false}},[lot.id]);if(par===null)return <div style={{fontSize:12,color:C.tM}}>Carico tracciabilita...</div>;if(par.length===0)return <div style={{fontSize:12,color:C.tM}}>Lotto di origine: non deriva da trasformazione o trasferimento.</div>;return <div style={{display:"flex",flexDirection:"column",gap:6}}><div style={{fontSize:11,fontWeight:800,color:C.acc,textTransform:"uppercase",letterSpacing:.8,display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}>Lotti padre ({par.length}){ddtAbc&&ddtAbc.length>0&&<span style={{fontWeight:700,color:C.b,background:C.bD,borderRadius:5,padding:"2px 8px",letterSpacing:.3,textTransform:"none"}}>DDT andata ABC: {ddtAbc.join(", ")}</span>}{lot.declassamento&&<span title={lot.declassamento} style={{fontWeight:700,color:C.oT,background:C.oD,borderRadius:5,padding:"2px 8px",letterSpacing:.3,textTransform:"none"}}>DECLASSATO · {String(lot.declassamento).replace(/^Declassamento\s*/,"")}</span>}{docA&&<span style={{fontWeight:700,color:C.g,background:C.gD,borderRadius:5,padding:"2px 8px",letterSpacing:.3,textTransform:"none"}}>Rientro: DDT ABC {docA.numero} del {fmtD(docA.data)}{lot.scadenza?" \u00b7 scad. "+fmtD(lot.scadenza):""}</span>}</div>{par.map(p=><div key={p.id} style={{display:"flex",gap:12,flexWrap:"wrap",alignItems:"center",padding:"6px 10px",background:C.zebra,borderRadius:6,fontSize:12}}><span style={{fontWeight:700,color:C.t}}>{p.lotto} - {p.imballo}</span><span style={{color:C.tM}}>{p.desc1} · {p.desc2} · {p.desc3}</span>{p.qScar!=null&&<span style={{fontFamily:"'DM Mono',monospace",color:C.acc}}>scaricati {Number(p.qScar).toLocaleString("it-IT")} kg</span>}<span style={{color:C.tM}}>racc. {p.anno_raccolta||"-"} · mag. {p.magazzino}</span>{p.ddtAnd&&<span style={{fontFamily:"'DM Mono',monospace",color:C.b,fontWeight:700}}>DDT and. {p.ddtAnd}</span>}<span style={{marginLeft:"auto",fontFamily:"'DM Mono',monospace",fontSize:11}}>M.O. <b style={{color:moP(p)>4?C.r:moP(p)>2?C.o:C.g}}>{pct(p.mo)}</b> · C.O. <b style={{color:coP(p)>4?C.r:coP(p)>2?C.o:C.g}}>{pct(p.co)}</b> · M.V. {pct(p.mv)} · C.V. {pct(p.cv)} · C.E. {pct(p.ce)} · RT {pct(p.rt)}</span></div>)}</div>;}

