  const all=rows||[];const anni=[...new Set(all.map(r=>String(r.anno)))].sort((a,b)=>b-a);if(fA&&!anni.includes(fA))anni.unshift(fA);
  const sh=all.filter(r=>{if(fA&&String(r.anno)!==fA)return false;if(fM&&r.mag_partenza!==fM)return false;if(fSt&&r.stato!==fSt)return false;if(q){const s=(fmtDdt(r.numero,r.serie,r.anno)+" "+(r.destinatario||"")+" "+(r.righe||[]).map(x=>x.lotto+" "+x.imballo).join(" ")).toUpperCase();if(!s.includes(q.toUpperCase()))return false}return true});
