const allocProp=(cands,need)=>{const tot=cands.reduce((a,c)=>a+c.av,0);if(tot<=0)return[];const out=cands.map(c=>({padre_id:c.id,qta:r2(need*c.av/tot),av:c.av}));const diff=r2(need-out.reduce((a,o)=>a+o.qta,0));if(Math.abs(diff)>0){const big=out.reduce((b,o)=>o.av-o.qta>b.av-b.qta?o:b,out[0]);big.qta=r2(big.qta+diff)}return out.filter(o=>o.qta>0).map(({padre_id,qta})=>({padre_id,qta}))};
