  for(let d=1;d<=8&&lev.length;d++){const ids=lev.map(l=>l.id);const br=await q(supabase.from("trasformazione_input").select("figlio_id,padre_id,qta").in("padre_id",ids));const sp=await q(supabase.from("lotti").select("id").in("lotto_padre",ids));const cid=new Set([...br.map(b=>b.figlio_id),...sp.map(s=>s.id)]);const todo=[...cid].filter(i=>!seenD.has(i));if(!todo.length)break;todo.forEach(i=>seenD.add(i));const cs=await q(supabase.from("lotti").select("*").in("id",todo));
    cs.forEach(c=>{const bs=br.filter(b=>b.figlio_id===c.id);const da=lev.filter(l=>bs.some(b=>b.padre_id===l.id)||c.lotto_padre===l.id);down.push({...c,liv:d,qDa:bs.length?bs.reduce((a,b)=>a+Number(b.qta||0),0):null,tipoLeg:bs.length?"lavorazione":"trasferimento parziale",da:da.map(f=>f.lotto+(f.imballo?" "+f.imballo:"")).join(", ")})});lev=cs}
  const allIds=[L0.id,...up.map(x=>x.id),...down.map(x=>x.id)];
  const trm=await q(supabase.from("movimenti").select("lotto_id,ddt,data").eq("tipo","TRASFERIMENTO").eq("magazzino","ABC Service").in("lotto_id",allIds));const andata={};trm.forEach(m=>{if(m.ddt&&(!andata[m.lotto_id]||String(m.data)>String(andata[m.lotto_id].data)))andata[m.lotto_id]=m});
  const dIds=[...new Set([L0,...up,...down].map(x=>x.doc_id).filter(Boolean))];let docs=[];if(dIds.length){try{docs=await q(supabase.from("doc_abc").select("id,numero,data").in("id",dIds))}catch(e){docs=[]}}const docOf=l=>{const d=docs.find(x=>x.id===l.doc_id);return d?"ABC "+d.numero+" del "+fmtD(d.data):""};
  const movL=await q(supabase.from("movimenti").select("*").eq("lotto_id",L0.id).order("data",{ascending:true}).order("id",{ascending:true}));
  const usc=await q(supabase.from("movimenti").select("*").eq("tipo","USCITA").in("lotto_id",[L0.id,...down.map(x=>x.id)]).order("data",{ascending:true}));const byId={};[L0,...down].forEach(x=>{byId[x.id]=x});
  // --- PDF
  const doc=new jsPDF({unit:"mm",format:"a4"});const W=210,H=297,M=14,R=W-M;const T=[44,36,24],TD=[107,94,79],TM=[154,141,126],AC=[184,137,46],BD=[226,221,212],ZB=[247,244,238];
  const val=(t,x,y,o)=>{o=o||{};doc.setFont("helvetica",o.bold?"bold":"normal");doc.setFontSize(o.size||9);doc.setTextColor(...(o.color||T));doc.text(String(t==null?"":t),x,y,o.align?{align:o.align}:{})};
