  val(L0.lotto+(L0.imballo?" \u00b7 "+L0.imballo:""),R,19,{bold:true,size:16,align:"right"});val("stampata il "+oggiS,R,25,{size:8,color:TD,align:"right"});hr(30,AC,0.6);
  const info=[["Tipo",L0.desc1],["Lavorazione",L0.desc2],["Calibro",L0.desc3||"-"],["Magazzino",L0.magazzino],["Kg iniziali",kgD(L0.q_iniz)],["Disponibili",kgD(dsp(L0))],["Annata raccolta",L0.anno_raccolta||"-"],["Lavorazione (sett./anno)",L0.sett_prod?L0.sett_prod+"/"+L0.anno:"-"],["Contratto / cliente",[L0.contratto,cli(L0.contratto)||L0.acquirente].filter(Boolean).join(" \u00b7 ")||"-"],["Scadenza",L0.scadenza?fmtD(L0.scadenza):"-"],["Merce",L0.conto_lavoro?"Conto lavoro (di terzi)":L0.intragruppo?"Venduta intragruppo":"Di propriet\u00e0"],["Rientro da ABC",docOf(L0)||"-"],...(L0.declassamento?[["Declassamento",L0.declassamento]]:[])];
  let y=37;const cw=(R-M)/4;info.forEach((it,i)=>{const x=M+(i%4)*cw,yy=y+Math.floor(i/4)*10;doc.setFont("helvetica","bold");doc.setFontSize(6.3);doc.setTextColor(...TM);doc.text(String(it[0]).toUpperCase(),x,yy);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.setTextColor(...T);doc.text(doc.splitTextToSize(String(it[1]),cw-3)[0],x,yy+4.5)});
  y+=Math.ceil(info.length/4)*10+1;val("Qualit\u00e0 %   M.V. "+pr(L0.mv)+"   M.O. "+pr(L0.mo)+"   C.V. "+pr(L0.cv)+"   C.O. "+pr(L0.co)+"   C.E. "+pr(L0.ce)+"   RT "+pr(L0.rt),M,y,{size:8.5,color:TD});y+=5;
  const sez=(title,sub,head,body,cs)=>{if(y>H-40){doc.addPage();y=18}hr(y,T,0.4);val(title,M,y+5.5,{bold:true,size:10});if(sub)val(sub,R,y+5.5,{size:7.5,color:TM,align:"right"});y+=8;
    if(!body.length){val("Nessun dato.",M,y+3,{size:8.5,color:TM});y+=9;return}
    autoTable(doc,{startY:y,margin:{left:M,right:M,top:16,bottom:18},head:[head],body,theme:"plain",styles:{font:"helvetica",fontSize:7.6,textColor:T,cellPadding:{top:1.6,bottom:1.6,left:1.3,right:1.3},overflow:"linebreak"},headStyles:{fontSize:6.2,fontStyle:"bold",textColor:TM},alternateRowStyles:{fillColor:ZB},columnStyles:cs||{},
      didParseCell:c=>{if(c.section==="head")c.cell.text=c.cell.text.map(t=>t.toUpperCase())},didDrawCell:c=>{if(c.section==="head"&&c.column.index===0){doc.setDrawColor(...AC);doc.setLineWidth(0.3);doc.line(M,c.cell.y+c.cell.height,R,c.cell.y+c.cell.height)}}});y=doc.lastAutoTable.finalY+7};
  const prod=l=>[l.desc1,l.desc2,l.desc3].filter(Boolean).join(" \u00b7 ");
  sez("Origine (a ritroso)",up.length?up.length+" lotti di provenienza":"lotto di origine",["Liv.","Lotto","Imballo","Prodotto","Annata","Kg usati","Verso","Mag.","DDT andata / rientro ABC","M.O.","C.O."],up.map(p=>[String(p.liv),p.lotto||"",p.imballo||"",prod(p)+(p.declassamento?" (DECLASSATO)":""),String(p.anno_raccolta||"-"),p.qScar!=null?kgD(p.qScar):"-",p.verso,p.magazzino||"",andata[p.id]?andata[p.id].ddt:(docOf(p)||""),pr(p.mo),pr(p.co)]),{0:{cellWidth:8},1:{fontStyle:"bold"},5:{halign:"right"},9:{halign:"right"},10:{halign:"right"}});
  sez("Destinazione (in avanti)",down.length?down.length+" lotti derivati":"",["Liv.","Lotto","Imballo","Prodotto","Kg da origine","Kg iniz.","Disp.","Mag.","Tipo legame","Da","Rientro ABC"],down.map(c=>[String(c.liv),c.lotto||"",c.imballo||"",prod(c)+(c.declassamento?" (DECLASSATO)":""),c.qDa!=null?kgD(c.qDa):"-",kgD(c.q_iniz),kgD(dsp(c)),c.magazzino||"",c.tipoLeg,c.da,docOf(c)]),{0:{cellWidth:8},1:{fontStyle:"bold"},4:{halign:"right"},5:{halign:"right"},6:{halign:"right"}});
  sez("Uscite (questo lotto e derivati)",usc.length?kgD(usc.reduce((a,m)=>a+Number(m.qta||0),0))+" kg":"",["Data","Lotto","Imballo","Kg","DDT","Cliente","Nota"],usc.map(m=>{const l=byId[m.lotto_id]||{};return[fmtD(m.data),m.lotto||l.lotto||"",m.imballo||l.imballo||"",kgD(m.qta),m.ddt||"",cli(m.contratto_id)||l.acquirente||"",m.nota||""]}),{1:{fontStyle:"bold"},3:{halign:"right"}});
  sez("Movimenti del lotto",movL.length+" movimenti",["Data","Tipo","Kg","Magazzino","DDT","Riferimento / nota","Utente"],movL.map(m=>[fmtD(m.data),m.tipo,kgD(m.qta),m.magazzino||"",m.ddt||"",m.nota||m.contratto_id||"",m.utente||""]),{2:{halign:"right"}});
