  const doBulkUscita=async()=>{if(loading)return;const lots=sorted.filter(l=>selIds.includes(l.id));if(lots.length===0){flash("err","Nessun lotto selezionato");return}const gen=dd.gen&&canGenDdt(lots);if(!gen&&!String(bDdt).trim()){flash("err","Inserisci il numero DDT");return}if(!dd.data){flash("err","Inserisci la data");return}let prep=null;if(gen){prep=ddtPrep(lots,"U");if(prep.err){flash("err",prep.err);return}}setLoading(true);const dt=dd.data;let saved=null;if(gen){try{prep.row.righe=lots.map(l=>ddtRiga(l,l.d));saved=await ddtOpen(prep.row)}catch(e){flash("err",e.message);setLoading(false);return}}const dStr=saved?fmtDdt(saved.numero,saved.serie,saved.anno):String(bDdt).trim();const dx=saved?{ddt:dStr,ddt_id:saved.id}:{ddt:dStr};let ok=0;const fail=[];const okR=[];const uCt=contratti.find(c=>c.id===uC);const uAcq=uC?(uCt?uCt.cliente:String(uA).trim()):String(uA).trim();for(const lot of lots){try{let cId=lot.contratto||"";if(!(lot.contratto||lot.acquirente)&&(uC||uAcq)){const{error:ea}=await supabase.from("lotti").update({contratto:uC||"",acquirente:uAcq}).eq("id",lot.id);if(ea)throw ea;cId=uC||""}const{error:me}=await supabase.from("movimenti").insert({tipo:"USCITA",data:dt,imballo:lot.imballo,lotto:lot.lotto,desc1:lot.desc1,desc2:lot.desc2,desc3:lot.desc3,qta:lot.d,magazzino:lot.magazzino,contratto_id:cId,lotto_id:lot.id,utente:CUR_EMAIL,...dx});if(me)throw me;await supabase.rpc("incrementa_mov",{lid:lot.id,q:lot.d});const ct=contratti.find(c=>c.id===cId&&(c.qta_tot-c.qta_evasa)>0);if(ct)await supabase.rpc("incrementa_evasa",{cid:ct.id,q:lot.d});ok++;okR.push(ddtRiga(lot,lot.d))}catch(e){fail.push(lot.lotto+"/"+lot.imballo)}}let fin=null;if(saved)fin=await ddtClose(saved,okR);const dMsg=fin?" \u00b7 DDT "+dStr+" generato":"";if(fail.length)flash("err","Uscita "+ok+" lotti"+dMsg+". NON riusciti ("+fail.length+"): "+fail.join(", "));else flash("ok","Uscita "+ok+" lotti"+dMsg);setSelIds([]);setBDdt("");setUMode(false);setUC("");setUA("");setDd(ddtNew("T"));setLoading(false);await reload()};
  const doBulkAssign=async()=>{if(loading)return;if(!aC&&!aA){flash("err","Seleziona contratto o acquirente");return}setLoading(true);const ct=contratti.find(c=>c.id===aC);const ids=sorted.filter(l=>selIds.includes(l.id)&&l.stato==="L").map(l=>l.id);for(const id of ids)await supabase.from("lotti").update({contratto:aC,acquirente:aC?ct?.cliente||aA:aA}).eq("id",id);setSelIds([]);setAMode(false);setAC("");setAA("");flash("ok","Assegnati "+ids.length+" lotti");setLoading(false);await reload()};
