      if(r.lotto_id&&cid.startsWith("SPLIT|")){const{data:child}=await supabase.from("lotti").select("id,mov,lotto_padre").eq("id",r.lotto_id).maybeSingle();if(child){if((child.mov||0)>0){flash("err","Il lotto trasferito ha gia movimenti: annulla prima quelli");return}if(child.lotto_padre)await supabase.rpc("incrementa_mov",{lid:child.lotto_padre,q:-r.qta});await supabase.from("lotti").delete().eq("id",child.id)}await supabase.from("movimenti").delete().match({tipo:"ENTRATA",lotto_id:r.lotto_id})}
